check_format_type(const char *ptr, int type, const char **estr)
{
        int quad = 0, h;
        size_t len, cnt;
        if (*ptr == '\0') {
                /* Missing format string; bad */
                *estr = "missing format spec";
                return -1;
        }

        switch (file_formats[type]) {
        case FILE_FMT_QUAD:
                quad = 1;
                /*FALLTHROUGH*/
        case FILE_FMT_NUM:
                if (quad == 0) {
                        switch (type) {
                        case FILE_BYTE:
                                h = 2;
                                break;
                        case FILE_SHORT:
                        case FILE_BESHORT:
                        case FILE_LESHORT:
                                h = 1;
                                break;
                        case FILE_LONG:
                        case FILE_BELONG:
                        case FILE_LELONG:
                        case FILE_MELONG:
                        case FILE_LEID3:
                        case FILE_BEID3:
                        case FILE_INDIRECT:
                                h = 0;
                                break;
                        default:
                                fprintf(stderr, "Bad number format %d", type);
                                abort();
                        }
                } else
                        h = 0;
                while (*ptr && strchr("-.#", *ptr) != NULL)
                        ptr++;
#define CHECKLEN() do { \
        for (len = cnt = 0; isdigit(CAST(unsigned char, *ptr)); ptr++, cnt++) \
                len = len * 10 + (*ptr - '0'); \
        if (cnt > 5 || len > 1024) \
                goto toolong; \
} while (/*CONSTCOND*/0)

                CHECKLEN();
                if (*ptr == '.')
                        ptr++;
                CHECKLEN();
                if (quad) {
                        if (*ptr++ != 'l')
                                goto invalid;
                        if (*ptr++ != 'l')
                                goto invalid;
                }

                switch (*ptr++) {
#ifdef STRICT_FORMAT    /* "long" formats are int formats for us */
                /* so don't accept the 'l' modifier */
                case 'l':
                        switch (*ptr++) {
                        case 'i':
                        case 'd':
                        case 'u':
                        case 'o':
                        case 'x':
                        case 'X':
                                if (h == 0)
                                        return 0;
                                /*FALLTHROUGH*/
                        default:
                                goto invalid;
                        }

                /*
                 * Don't accept h and hh modifiers. They make writing
                 * magic entries more complicated, for very little benefit
                 */
                case 'h':
                        if (h-- <= 0)
                                goto invalid;
                        switch (*ptr++) {
                        case 'h':
                                if (h-- <= 0)
                                        goto invalid;
                                switch (*ptr++) {
                                case 'i':
                                case 'd':
                                case 'u':
                                case 'o':
                                case 'x':
                                case 'X':
                                        return 0;
                                default:
                                        goto invalid;
                                }
                        case 'i':
                        case 'd':
                        case 'u':
                        case 'o':
                        case 'x':
                        case 'X':
                                if (h == 0)
                                        return 0;
                                /*FALLTHROUGH*/
                        default:
                                goto invalid;
                        }
#endif
                case 'c':
                        if (h == 2)
                                return 0;
                        goto invalid;
                case 'i':
                case 'd':
                case 'u':
                case 'o':
                case 'x':
                case 'X':
#ifdef STRICT_FORMAT
                        if (h == 0)
                                return 0;
                        /*FALLTHROUGH*/
#else
                        return 0;
#endif
                default:
                        goto invalid;
                }

        case FILE_FMT_FLOAT:
        case FILE_FMT_DOUBLE:
                if (*ptr == '-')
                        ptr++;
                if (*ptr == '.')
                        ptr++;
                CHECKLEN();
                if (*ptr == '.')
                        ptr++;
                CHECKLEN();
                switch (*ptr++) {
                case 'e':
                case 'E':
                case 'f':
                case 'F':
                case 'g':
                case 'G':
                        return 0;

                default:
                        goto invalid;
                }


        case FILE_FMT_STR:
                if (*ptr == '-')
                        ptr++;
                while (isdigit(CAST(unsigned char, *ptr)))
                        ptr++;
                if (*ptr == '.') {
                        ptr++;
                        while (isdigit(CAST(unsigned char , *ptr)))
                                ptr++;
                }

                switch (*ptr++) {
                case 's':
                        return 0;
                default:
                        goto invalid;
                }

        default:
                /* internal error */
                fprintf(stderr, "Bad file format %d", type);
                abort();
        }
invalid:
        *estr = "not valid";
        return -1;
toolong:
        *estr = "too long";
        return -1;
}

/*
 * Check that the optional printf format in description matches
 * the type of the magic.
 */
private int
check_format(struct magic_set *ms, struct magic *m)
{
        char *ptr;
        const char *estr;

        for (ptr = m->desc; *ptr; ptr++)
                if (*ptr == '%')
                        break;
        if (*ptr == '\0') {
                /* No format string; ok */
                return 1;
        }

        assert(file_nformats == file_nnames);

        if (m->type >= file_nformats) {
                file_magwarn(ms, "Internal error inconsistency between "
                    "m->type and format strings");
                return -1;
        }
        if (file_formats[m->type] == FILE_FMT_NONE) {
                file_magwarn(ms, "No format string for `%s' with description "
                    "`%s'", m->desc, file_names[m->type]);
                return -1;
        }

        ptr++;
        if (check_format_type(ptr, m->type, &estr) == -1) {
                /*
                 * TODO: this error message is unhelpful if the format
                 * string is not one character long
                 */
                file_magwarn(ms, "Printf format is %s for type "
                    "`%s' in description `%s'", estr,
                    file_names[m->type], m->desc);
                return -1;
        }

        for (; *ptr; ptr++) {
                if (*ptr == '%') {
                        file_magwarn(ms,
                            "Too many format strings (should have at most one) "
                            "for `%s' with description `%s'",
                            file_names[m->type], m->desc);
                        return -1;
                }
        }
        return 0;
}

